/// <summary>
/// find
/// </summary>
/// <param name = "_nDX_SNItemGroupDeactive">NDXSNItemGroupDeactiveTmp record</param>
/// <param name = "_alliance">alliance</param>
/// <param name = "_child">child</param>
/// <param name = "_company">company</param>
/// <param name = "_artGrp">item group</param>
/// <param name = "_update">for update</param>
/// <returns>NDXSNItemGroupDeactiveTmp record</returns>
static NDXSNItemGroupDeactiveTmp find(NDXSNItemGroupDeactiveTmp _nDX_SNItemGroupDeactive,
                                   CustAccount      _alliance,
                                   CustAccount      _child,
                                   NDXCompanyBE     _company,
                                   NDXItemGroup     _artGrp,
                                   boolean          _update = false)
{

    NDXSNItemGroupDeactiveTmp nDX_SNItemGroupDeactive = _nDX_SNItemGroupDeactive;

    nDX_SNItemGroupDeactive.selectForUpdate(_update);

    select firstonly nDX_SNItemGroupDeactive
        where nDX_SNItemGroupDeactive.Alliance  == _alliance
            && nDX_SNItemGroupDeactive.Child     == _child
            && nDX_SNItemGroupDeactive.Company   == _company
            && nDX_SNItemGroupDeactive.ArtGrp    == _artGrp;

    return nDX_SNItemGroupDeactive;
}

/// <summary>
/// find or create
/// </summary>
/// <param name = "_nDX_SNItemGroupDeactive">NDXSNItemGroupDeactiveTmp record</param>
/// <param name = "_alliance">alliance</param>
/// <param name = "_child">child</param>
/// <param name = "_company">company</param>
/// <param name = "_artGrp">item group</param>
/// <returns>NDXSNItemGroupDeactiveTmp record</returns>
static NDXSNItemGroupDeactiveTmp findOrCreate(NDXSNItemGroupDeactiveTmp _nDX_SNItemGroupDeactive,
                                           CustAccount       _alliance,
                                           CustAccount       _child,
                                           NDXCompanyBE      _company,
                                           NDXItemGroup _artGrp)

{
    NDXSNItemGroupDeactiveTmp nDX_SNItemGroupDeactive = _nDX_SNItemGroupDeactive;

    nDX_SNItemGroupDeactive = NDXSNItemGroupDeactiveTmp::find(nDX_SNItemGroupDeactive, _alliance, _child, _company, _artGrp);

    if (!nDX_SNItemGroupDeactive)
    {
        nDX_SNItemGroupDeactive.Alliance        = _alliance;
        nDX_SNItemGroupDeactive.Child           = _child;
        nDX_SNItemGroupDeactive.Company         = _company;
        nDX_SNItemGroupDeactive.ArtGrp          = _artGrp;
        nDX_SNItemGroupDeactive.PriceDiscName   = PriceDiscGroup::NDXfind(ModuleInventCustVend::Invent, PriceGroupType::LineDiscGroup, _artGrp, NDXHelperCommon::NDXCompanys2CompanyId(_company)).Name;
        nDX_SNItemGroupDeactive.insert();
    }

    return nDX_SNItemGroupDeactive;
}
